script:
(function () {
  'use strict';
  // Weighted average cost of capital from market values.
  //   V = E + D + P;  WACC = E/V * Re + D/V * Rd * (1 - T) + P/V * Rp.
  //   Equity E is entered directly or as share price * shares outstanding. Preferred stock is optional
  //   (P = 0 drops it). Interest tax shield per year = D * Rd * T. Default tax rate 21% = US federal
  //   corporate rate (IRC section 11(b)); the user can change it.
  // Verified in Node (scratchpad tests/b2biz), hand-checked: E $6,000,000 at 10%, D $4,000,000 at 6%,
  //   tax 21% -> after-tax debt 4.74%, WACC 7.896%; E 500 at 12%, preferred 100 at 8%, D 400 at 7%,
  //   tax 30% -> WACC 8.76%; E $6m at 10%, D $4m at 6%, tax 0 -> 8.40%; all-equity -> WACC = cost of
  //   equity. Zero total capital, blank or negative input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var dec = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- calc ---
  function wacc(E, Re, D, Rd, T, P, Rp) {
    var V = E + D + P;
    if (!(V > 0)) return null;
    var rdAfter = Rd * (1 - T);
    var r = {
      total: V, wE: E / V, wD: D / V, wP: P / V, rdAfter: rdAfter,
      cE: E / V * Re, cD: D / V * rdAfter, cP: P / V * Rp,
      de: E > 0 ? D / E : null, shield: D * Rd * T
    };
    r.wacc = r.cE + r.cD + r.cP;
    return r;
  }
  // --- end calc ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pct(x, digits) { return (x * 100).toFixed(digits === undefined ? 2 : digits) + '%'; }

  var OUT = ['wcWacc', 'wcAfterTax', 'wcTotal', 'wcWeightE', 'wcWeightD', 'wcWeightP', 'wcDe', 'wcShield',
             'wcTValE', 'wcTWE', 'wcTCE', 'wcTContE', 'wcTValD', 'wcTWD', 'wcTCD', 'wcTContD',
             'wcTValP', 'wcTWP', 'wcTCP', 'wcTContP', 'wcTValT', 'wcTWT', 'wcTContT'];

  function update() {
    var byShares = el('wcEqModeShares').checked;
    el('wcEqValueBox').hidden = byShares;
    el('wcEqSharesBox').hidden = !byShares;
    var E = byShares ? read('wcPrice') * read('wcShares') : read('wcEquity');
    var Re = read('wcCostEquity', true), D = read('wcDebt', true), Rd = read('wcCostDebt', true),
        T = read('wcTax', true), P = read('wcPref', true), Rp = read('wcCostPref', true);
    var msg = '';
    if (isNaN(E) || E < 0 || (byShares && (read('wcPrice') < 0 || read('wcShares') < 0)))
      msg = byShares ? 'Enter a share price and number of shares of 0 or more.' : 'Enter a market value of equity of $0 or more.';
    else if ([D, P].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Market values cannot be negative.';
    else if ([Re, Rd, Rp].some(function (v) { return isNaN(v) || v < 0 || v > 100; })) msg = 'Enter each cost of capital from 0% to 100%.';
    else if (isNaN(T) || T < 0 || T > 100) msg = 'Enter a tax rate from 0% to 100%.';
    else if (E + D + P <= 0) msg = 'Enter a market value for at least one source of capital.';
    var error = el('wcError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { OUT.forEach(function (id) { setText(id, '–'); }); return; }

    var r = wacc(E, Re / 100, D, Rd / 100, T / 100, P, Rp / 100);
    setText('wcWacc', pct(r.wacc, 3));
    setText('wcAfterTax', pct(r.rdAfter, 3));
    setText('wcTotal', money.format(r.total));
    setText('wcWeightE', pct(r.wE));
    setText('wcWeightD', pct(r.wD));
    setText('wcWeightP', pct(r.wP));
    setText('wcDe', r.de === null ? 'n/a' : dec.format(r.de));
    setText('wcShield', money.format(r.shield));
    setText('wcTValE', money.format(E)); setText('wcTWE', pct(r.wE)); setText('wcTCE', pct(Re / 100, 3)); setText('wcTContE', pct(r.cE, 3));
    setText('wcTValD', money.format(D)); setText('wcTWD', pct(r.wD)); setText('wcTCD', pct(r.rdAfter, 3)); setText('wcTContD', pct(r.cD, 3));
    setText('wcTValP', money.format(P)); setText('wcTWP', pct(r.wP)); setText('wcTCP', pct(Rp / 100, 3)); setText('wcTContP', pct(r.cP, 3));
    setText('wcTValT', money.format(r.total)); setText('wcTWT', pct(1)); setText('wcTContT', pct(r.wacc, 3));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('wcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
